nextflow_process {

    name "Test Process SALTSHAKER_CALL"
    script "../main.nf"
    process "SALTSHAKER_CALL"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "saltshaker"
    tag "saltshaker/call"

    test("call - tsv") {

        when {
            process {
                """

                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/mitosalt/test_mitosalt.breakpoint', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/mitosalt/test_mitosalt.cluster', checkIfExists: true),
                ]

                input[1] = [
                    [ id:'hg38' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/human_mt_rCRS.fasta', checkIfExists: true),
                ]

                input[2] = 15
                input[3] = 0.01
                input[4] = 16569
                input[5] = 16081
                input[6] = 407
                input[7] = 5730
                input[8] = 5763

                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out)
                ).match() }
            )
        }

    }

    test("call - tsv - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/mitosalt/test_mitosalt.breakpoint', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/mitosalt/test_mitosalt.cluster', checkIfExists: true),
                ]

                input[1] = [
                    [ id:'hg38' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/human_mt_rCRS.fasta', checkIfExists: true),
                ]

                input[2] = 15
                input[3] = 0.01
                input[4] = 16569
                input[5] = 16081
                input[6] = 407
                input[7] = 5730
                input[8] = 5763

                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out)
                ).match() }
            )
        }

    }

}
